import{a as g,b as v}from"./chunk-FX74KGGH.js";import{p as m,q as u}from"./chunk-GJ3JC5JV.js";import{g as d}from"./chunk-BXOCNT2X.js";import"./chunk-XWS7YVNN.js";import{Mb as l,Nb as s,Ob as n,Pb as a,fb as r,hc as t,ic as c,sb as p}from"./chunk-VSTHX7ND.js";import"./chunk-ACKELEN3.js";var S=(e,o)=>o.titolo,C=(e,o)=>o.nome;function b(e,o){if(e&1&&(n(0,"dt"),t(1),a(),n(2,"dd"),t(3),a()),e&2){let i=o.$implicit;r(),c(i.nome),r(2),c(i.testo)}}function z(e,o){if(e&1&&(n(0,"section")(1,"h2"),t(2),a(),n(3,"dl"),l(4,b,4,2,null,null,C),a()()),e&2){let i=o.$implicit;r(2),c(i.titolo),r(2),s(i.voci)}}var x=[{titolo:"In cima alla pagina",voci:[{nome:"Ricerca predefinita",testo:"Il riquadro con la stella viola \xE8 la ricerca che l'agente usa da solo, ogni giorno alle 7:30 e alle 19:30. Sotto il nome trovi un riassunto dei criteri principali."},{nome:"Cerca ora",testo:"Lancia subito un giro sulla ricerca predefinita e ti porta in Offerte, dove vedi \xABRicerca in corso\xBB finch\xE9 non finisce. Si fa un giro alla volta: una ricerca ogni 15 minuti, al massimo 3 ogni 2 ore."},{nome:"Le tue ricerche",testo:"Puoi tenerne pi\xF9 di una, per esempio una per Milano e una da remoto. Tocca una ricerca per aprirla e modificarla. Ogni ricerca ha i suoi risultati, divisi in Offerte."},{nome:"Nuova ricerca",testo:"Apre un modulo vuoto. Se hai gi\xE0 un profilo, ti chiede se tenerlo per la nuova ricerca o ripartire da zero."},{nome:"Nome della ricerca",testo:"Serve a riconoscerla nell'elenco e in Offerte. Se lo lasci vuoto lo scelgo io, dalle parole chiave e dalla localit\xE0."},{nome:"Rendi predefinita",testo:"Dal prossimo giro l'agente user\xE0 questa ricerca al posto di quella attuale. Si pu\xF2 usare solo dopo aver salvato le modifiche."},{nome:"Svuota tutti i campi",testo:"Azzera il modulo, ma il CV gi\xE0 caricato resta. Non cambia nulla finch\xE9 non premi Salva, e con \xABAnnulla\xBB nel messaggio torni com'eri."}]},{titolo:"Da dove parti?",voci:[{nome:"La tua ricerca in una frase",testo:"Scrivi cosa cerchi, per esempio \xABSviluppatore Java senior da remoto o a Milano, partita IVA, almeno 300 euro al giorno, niente stage\xBB, e premi \xABCompila i campi\xBB. Le parole si sommano a quelle gi\xE0 presenti, gli altri criteri citati sostituiscono i vecchi. Controlla i campi e salva: il CV non serve."},{nome:"Dal CV",testo:"Carichi il file o incolli il testo, dopo aver dato il consenso. Il file viene letto nel tuo browser e parte solo il testo, dopo la tua conferma. In pochi minuti l'agente propone profilo e parole chiave: tocca una parola per toglierla, poi \xABApplica alla ricerca\xBB. Senza CV le ricerche funzionano comunque, il match si basa sul profilo."},{nome:"A mano",testo:"Compili direttamente i campi qui sotto. \xC8 la scelta di partenza per una ricerca gi\xE0 compilata."}]},{titolo:"Cosa cercare",voci:[{nome:"Ruoli e parole chiave",testo:"I ruoli e le tecnologie da cercare negli annunci. Scrivi una parola e premi Invio; sotto compaiono alcune parole suggerite da aggiungere con un tocco. Serve almeno una parola chiave oppure il profilo: se le lasci vuote, l'agente le ricava dal profilo."}]},{titolo:"Dove e come",voci:[{nome:"Modalit\xE0 di lavoro",testo:"100% remoto, Ibrido, In sede: scegline una o pi\xF9. Nessuna scelta significa tutte."},{nome:"Max giorni in sede al mese",testo:"Per gli annunci ibridi o in sede: quanti giorni al mese sei disposto a lavorare in ufficio, da 0 a 31."},{nome:"Localit\xE0 accettate",testo:"Una regione o una citt\xE0, per esempio Trentino-Alto Adige. Conta per gli annunci ibridi o in sede. Mentre scrivi compaiono alcune localit\xE0 gi\xE0 note."},{nome:"Contratto",testo:"Partita IVA / Freelance e Dipendente: scegline uno o entrambi. Nessuna scelta significa tutti. Il campo del compenso compare solo per i contratti a cui si riferisce."},{nome:"Compenso minimo",testo:"Compare con la Partita IVA / Freelance: il compenso giornaliero minimo in euro. Gli annunci che indicano un compenso pi\xF9 basso vengono scartati."},{nome:"RAL minima",testo:"Compare con il contratto da Dipendente: la retribuzione annua lorda minima in euro. Gli annunci che indicano una cifra pi\xF9 bassa vengono scartati."}]},{titolo:"Altri filtri",voci:[{nome:"Altri filtri",testo:"Un blocco chiuso di partenza, per tenere la pagina corta. Accanto al titolo vedi quanti filtri sono attivi: se ce n'\xE8 uno con un valore sbagliato, il blocco si apre da solo."},{nome:"Parole da escludere",testo:"Gli annunci che contengono queste parole vengono scartati, per esempio \xABstage\xBB. Anche qui ci sono parole suggerite."},{nome:"Escludi ruoli junior",testo:"Scarta gli annunci pensati per chi ha poca esperienza."},{nome:"Annunci pubblicati da al massimo",testo:"L'et\xE0 massima degli annunci, in giorni, da 1 a 365. Se lo lasci vuoto vale 30. Un annuncio pi\xF9 vecchio viene scartato anche se la pagina \xE8 ancora online; se la pagina non mostra nessuna data, finisce tra gli spunti."},{nome:"Aziende da non proporre",testo:"I nomi delle aziende da escludere. Le aziende a cui ti sei gi\xE0 candidato sono escluse da sole."}]},{titolo:"Profilo",voci:[{nome:"Competenze ed esperienza",testo:"Un testo libero, fino a 4000 caratteri: ruolo attuale, anni di esperienza, tecnologie, settori, lingue e, se vuoi, cosa ti manca per i ruoli a cui punti. Serve a valutare quanto ogni offerta corrisponde a te (match alto, medio, basso) e a scrivere cosa manca. Non scrivere nome, recapiti o altri dati personali. Si pu\xF2 compilare dal CV."}]},{titolo:"Salvare e lanciare",voci:[{nome:"Salva",testo:"Salva le modifiche. Se hai cambiato la ricerca predefinita, l'agente la user\xE0 dal prossimo giro."},{nome:"Salva e cerca ora",testo:"Salva e lancia la ricerca una volta, poi ti porta in Offerte. Se la ricerca aperta non \xE8 la predefinita, la predefinita e i giri automatici non cambiano."},{nome:"Altro",testo:"Raccoglie le azioni meno frequenti: \xABSalva come nuova\xBB crea una copia con un altro nome; \xABSalva e usa per l'agente\xBB salva e rende predefinita la ricerca aperta; \xABElimina\xBB la cancella, e se \xE8 la predefinita ti chiede quale la sostituisce."}]},{titolo:"Dopo la ricerca",voci:[{nome:"Offerte",testo:"I risultati compaiono in Offerte, divisi per ricerca: il filtro \xABRicerca\xBB sceglie quale guardare. Con \xABCerca ora\xBB o \xABSalva e cerca ora\xBB ci vai da solo."},{nome:"Match",testo:"Alto, medio o basso: quanto l'offerta corrisponde al tuo profilo e, se l'hai caricato, al tuo CV."},{nome:"Spunti",testo:"Annunci che sembrano interessanti ma senza data o senza un link diretto: vanno verificati prima di candidarti."},{nome:"Scarta",testo:"Un'offerta scartata non viene riproposta nei giri successivi."}]}],f=class e{sezioni=x;static \u0275fac=function(i){return new(i||e)};static \u0275cmp=p({type:e,selectors:[["app-guida-ricerca"]],decls:12,vars:0,consts:[[1,"guida"],[1,"intestazione"],["mat-stroked-button","","routerLink","/ricerca"],[1,"secondario"]],template:function(i,h){i&1&&(n(0,"article",0)(1,"div",1)(2,"h1"),t(3,"Come funziona la ricerca"),a(),n(4,"a",2)(5,"mat-icon"),t(6,"arrow_back"),a(),t(7," Torna alla ricerca"),a()(),n(8,"p",3),t(9," Una ricerca dice all'agente cosa cercare. Quella con la stella viola, la predefinita, \xE8 la sola che l'agente usa da solo, ogni giorno alle 7:30 e alle 19:30. Le altre le lanci tu, una volta, con \xABSalva e cerca ora\xBB. I risultati arrivano in Offerte, divisi per ricerca. Qui sotto trovi ogni campo, nell'ordine in cui compare nella pagina. "),a(),l(10,z,6,1,"section",null,S),a()),i&2&&(r(10),s(h.sezioni))},dependencies:[d,u,m,v,g],styles:[".guida[_ngcontent-%COMP%]{max-width:820px}section[_ngcontent-%COMP%]{margin:0 0 16px;padding:16px;border:1px solid var(--jt-bordo);border-radius:14px;background:var(--jt-scheda)}h2[_ngcontent-%COMP%]{margin:0 0 8px;font-size:1.05rem;font-weight:600}dl[_ngcontent-%COMP%]{margin:0}dt[_ngcontent-%COMP%]{margin-top:12px;font-weight:600}dt[_ngcontent-%COMP%]:first-child{margin-top:0}dd[_ngcontent-%COMP%]{margin:2px 0 0;color:var(--jt-testo-secondario);overflow-wrap:anywhere}"]})};export{f as GuidaRicercaComponent};
